-- Shows reais confirmados em São Paulo (pesquisa de 25/11/2026), ligados aos lugares de venues_sp.sql.
-- Criados em nome da primeira conta moderadora. Reexecutável.
insert into public.events (id, title, description, category_id, status, starts_at, venue_name, address, latitude, longitude, price_min_cents, price_max_cents, venue_id, created_by, moderated_by, moderated_at)
select x.id::uuid, x.title, x.description, x.category_id, x.status, x.starts_at, x.venue_name, x.address, x.lat, x.lon, x.pmin, x.pmax, x.venue_id, m.id, m.id, now()
from (values
('69d7bdb3-356e-56e0-9bc3-69aad7a98e80', 'Falamansa – despedida da turnê Universos', 'Show de encerramento da turnê Universos. Casa abre às 21h. 18 anos. Fonte: baressp.com.br e visitesaopaulo.com.', (select id from event_categories where slug = 'shows'), 'approved', timestamptz '2026-11-27 21:00:00-03', 'Audio', 'Avenida Francisco Matarazzo, 694, Água Branca — São Paulo', -23.528535, -46.669524, null::int, null::int, 'cfe7f246-9ef6-5dc5-b6c8-46f8bb1d9761'::uuid),
('770f8ea0-87b2-5aa2-9e70-da764d731c4d', 'BABYMETAL', 'Show único no Brasil. Portões às 18h, show às 21h. Ingressos esgotados (pista de R$ 197,50 a R$ 395). Fonte: billboard.com.br e rollingstone.com.br.', (select id from event_categories where slug = 'shows'), 'approved', timestamptz '2026-11-28 21:00:00-03', 'Espaço Unimed', 'Rua Tagipuru, 795, Barra Funda — São Paulo', -23.528041, -46.668013, 19750, 39500, '1ee51640-4e9a-5c44-a77d-2fec2a6f8d14'::uuid),
('d40a33a5-8c99-53b6-8c1c-d49598efefad', 'Daniel Caesar', 'Portões às 19h, show às 21h. Fonte: rollingstone.com.br.', (select id from event_categories where slug = 'shows'), 'approved', timestamptz '2026-12-02 21:00:00-03', 'Suhai Music Hall', 'Avenida das Nações Unidas, 22540, Jurubatuba — São Paulo', -23.680308, -46.699061, null, null, '2682e6a1-392e-5072-9a9c-6423b672d4e5'::uuid),
('99d09b31-626a-57fc-83e4-03492e596a0b', 'Ed Sheeran – Loop Tour', 'Portões às 16h, abertura com FINNEAS às 19h30, Ed Sheeran às 21h. Fonte: rollingstone.com.br.', (select id from event_categories where slug = 'shows'), 'approved', timestamptz '2026-12-05 21:00:00-03', 'Allianz Parque', 'Rua Palestra Itália, 200, Perdizes — São Paulo', -23.527497, -46.678528, null, null, 'e801ec4f-1d0a-51e4-b4b2-a2428de061a5'::uuid)
) as x(id, title, description, category_id, status, starts_at, venue_name, address, lat, lon, pmin, pmax, venue_id)
cross join lateral (select id from public.profiles where is_moderator and not coalesce(is_demo, false) order by created_at limit 1) m
on conflict (id) do update set title = excluded.title, description = excluded.description, starts_at = excluded.starts_at,
  venue_name = excluded.venue_name, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude,
  price_min_cents = excluded.price_min_cents, price_max_cents = excluded.price_max_cents, venue_id = excluded.venue_id, status = 'approved';
